<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{AuditLog,Review}; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\View\View;
class ReviewController extends Controller {public function index(Request $r):View{$q=Review::with(['user','booking.property'])->latest();if($r->filled('status'))$q->where('status',$r->status);return view('admin.reviews.index',['reviews'=>$q->paginate(10)->withQueryString()]);} public function update(Request $r,Review $review):RedirectResponse{$d=$r->validate(['status'=>'required|in:pending,approved,hidden,archived,flagged','featured'=>'nullable|boolean','admin_reply'=>'nullable|string|max:2000']);$old=$review->toArray();$review->update($d+['featured'=>$r->boolean('featured'),'moderated_by'=>$r->user()->id,'moderated_at'=>now()]);AuditLog::record('review.moderated',$review,$old,$review->toArray());return back()->with('success','Review updated.');}}
